using System.Windows;using System.Windows.Controls;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class RestoreView:System.Windows.Controls.UserControl{public RestoreView(){InitializeComponent();}async void Preflight_Click(object s,RoutedEventArgs e){if(DataContext is RestoreViewModel m)await m.PreflightAsync();}async void Restore_Click(object s,RoutedEventArgs e){if(DataContext is not RestoreViewModel m)return;if(System.Windows.MessageBox.Show("Restore دیتابیس جدید اجرا شود؟ قبل از ادامه نام مقصد و فایل‌ها را بررسی کنید.","تأیید Restore",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Warning)!=System.Windows.MessageBoxResult.Yes)return;await m.ExecuteAsync();}}